# =========================================
# 辅助函数：初始化项目级配置目录
# - .opencode/ = OpenCode 原生（skill/, command/, agent/）
# - .claude/rules/ = 条件规则（仅 Claude 兼容层支持）
# =========================================
_ocd_init_project_config() {
  local PROJECT_DIR="$1"

  # OpenCode 原生目录（单数）
  mkdir -p "$PROJECT_DIR/.opencode"/{skill,command,agent}

  # Claude 兼容层（仅 rules）
  mkdir -p "$PROJECT_DIR/.claude/rules"
}

